#!/usr/bin/env node

import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..', '..', '..', '..');
export const s5ConfigReaderArtifactPath = 'deploy/postgres/s5-config-reader-runtime.sql';

export function renderS5ConfigReaderSql() {
  return `-- S5-2 least-privilege restricted settings reader.
-- Generated by docs/_TODO/SAAS_FOUNDATION/scripts/s5-config-reader-sql.mjs.
-- Do not edit this artifact by hand.
\\set ON_ERROR_STOP on
\\pset pager off

\\if :{?s5_config_reader_login_role}
\\else
\\echo 'FATAL: missing s5_config_reader_login_role'
SELECT 1 / 0 AS s5_config_reader_login_role_missing;
\\endif

SELECT EXISTS (
  SELECT 1 FROM pg_roles WHERE rolname = :'s5_config_reader_login_role'
)::int AS s5_config_reader_login_exists \\gset
\\if :s5_config_reader_login_exists
\\else
\\echo 'FATAL: operator-created config-reader LOGIN role is missing'
SELECT 1 / 0 AS s5_config_reader_login_missing;
\\endif

BEGIN;

\\if :{?s5_config_reader_down}
DROP POLICY IF EXISTS s5_config_reader_restricted_read ON public.system_settings;
SELECT format('REVOKE app_config_reader FROM %I', :'s5_config_reader_login_role')
WHERE EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_config_reader')
\\gexec
DO $down_role$
BEGIN
  -- Keep DOWN repeatable: a second invocation still reaches the same explicit REVOKE/DROP sequence.
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_config_reader') THEN
    CREATE ROLE app_config_reader NOLOGIN NOINHERIT NOBYPASSRLS;
  END IF;
END
$down_role$;
REVOKE ALL PRIVILEGES ON DATABASE :DBNAME FROM app_config_reader;
REVOKE ALL PRIVILEGES ON SCHEMA public, app FROM app_config_reader;
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public FROM app_config_reader;
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA integrator FROM app_config_reader;
REVOKE ALL PRIVILEGES ON ALL ROUTINES IN SCHEMA app FROM app_config_reader;
DROP ROLE IF EXISTS app_config_reader;
COMMIT;
\\echo 'S5 config-reader DOWN complete.'
\\quit
\\endif

DO $roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_config_reader') THEN
    CREATE ROLE app_config_reader NOLOGIN NOINHERIT NOBYPASSRLS;
  END IF;
END
$roles$;

ALTER ROLE app_config_reader NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
ALTER ROLE :"s5_config_reader_login_role" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;

-- Remove every stale membership edge touching the managed capability/login, then restore one SET-only edge.
SELECT format('REVOKE %I FROM %I', granted.rolname, member.rolname)
FROM pg_auth_members membership
JOIN pg_roles granted ON granted.oid = membership.roleid
JOIN pg_roles member ON member.oid = membership.member
WHERE member.rolname IN ('app_config_reader', :'s5_config_reader_login_role')
   OR granted.rolname IN ('app_config_reader', :'s5_config_reader_login_role')
ORDER BY granted.rolname, member.rolname
\\gexec
GRANT app_config_reader TO :"s5_config_reader_login_role"
  WITH ADMIN FALSE, INHERIT FALSE, SET TRUE;

REVOKE ALL PRIVILEGES ON DATABASE :DBNAME FROM :"s5_config_reader_login_role", app_config_reader;
REVOKE ALL PRIVILEGES ON SCHEMA public, app FROM :"s5_config_reader_login_role", app_config_reader;
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public FROM :"s5_config_reader_login_role", app_config_reader;
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA integrator FROM :"s5_config_reader_login_role", app_config_reader;
REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public FROM :"s5_config_reader_login_role", app_config_reader;
REVOKE ALL PRIVILEGES ON ALL ROUTINES IN SCHEMA app FROM :"s5_config_reader_login_role", app_config_reader;

GRANT CONNECT ON DATABASE :DBNAME TO :"s5_config_reader_login_role";
GRANT USAGE ON SCHEMA public, app TO app_config_reader;
GRANT SELECT ON TABLE public.system_settings TO app_config_reader;
GRANT EXECUTE ON FUNCTION
  app.install_signed_context(text, integer, bigint, uuid, uuid, bigint, text),
  app.current_org_id(),
  app.release_principal_context()
  TO app_config_reader;

-- Explicitly keep every non-target settings surface closed.
REVOKE ALL PRIVILEGES ON TABLE
  public.system_settings_audit
  FROM :"s5_config_reader_login_role", app_config_reader;

ALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.system_settings FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS s5_config_reader_restricted_read ON public.system_settings;
CREATE POLICY s5_config_reader_restricted_read ON public.system_settings
  FOR SELECT TO app_config_reader
  USING (
    organization_id IS NULL
    OR (app.current_org_id() IS NOT NULL AND organization_id = app.current_org_id())
  );

-- Static privilege/membership tripwires are part of the repeatable artifact, not only the smoke.
SELECT 1 / (
  pg_has_role(:'s5_config_reader_login_role', 'app_config_reader', 'MEMBER')
  AND NOT pg_has_role(:'s5_config_reader_login_role', 'app_staff', 'MEMBER')
  AND NOT pg_has_role(:'s5_config_reader_login_role', 'app_patient', 'MEMBER')
  AND NOT pg_has_role('app_config_reader', 'app_staff', 'MEMBER')
  AND NOT pg_has_role('app_config_reader', 'app_patient', 'MEMBER')
)::int AS s5_config_reader_membership_closed;
SELECT 1 / (
  has_table_privilege('app_config_reader', 'public.system_settings', 'SELECT')
  AND NOT has_table_privilege('app_config_reader', 'public.system_settings', 'INSERT,UPDATE,DELETE')
  AND NOT has_table_privilege('app_config_reader', 'public.system_settings_audit', 'SELECT,INSERT,UPDATE,DELETE')
)::int AS s5_config_reader_acl_closed;

COMMIT;
\\echo 'S5 config-reader UP complete.'
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const command = process.argv[2] ?? '--stdout';
  const artifact = renderS5ConfigReaderSql();
  if (command === '--stdout') {
    process.stdout.write(artifact);
  } else if (command === '--write') {
    writeFileSync(path.join(repoRoot, s5ConfigReaderArtifactPath), artifact);
    console.log(`wrote ${s5ConfigReaderArtifactPath}`);
  } else {
    throw new Error(`Unsupported command ${command}. Use --stdout or --write.`);
  }
}
